          var parent = entry.target.parentElement;
          var siblings = parent ? Array.from(parent.children) : [];
          var index = siblings.indexOf(entry.target);
          entry.target.style.transitionDelay = (index * 0.1) + 's';
          entry.target.style.opacity = '1';
